#ifndef ZEPHYR_TESTS_SUBSYS_FS_FAT_FS_API_SRC_TEST_FAT_H_
#define ZEPHYR_TESTS_SUBSYS_FS_FAT_FS_API_SRC_TEST_FAT_H_

#include <zephyr/ztest.h>
#include <zephyr/fs/fs.h>
#include <zephyr/fs/fat_fs.h>

#if defined(CONFIG_FAT_FS_ACCESS_DISK_DRIVER)
#define DISK_NAME "NAND"
#define DISK_MOUNT_PT "/nand"
#elif defined(CONFIG_FAT_FS_ACCESS_RAMDISK)
#define DISK_NAME "RAM"
#define DISK_MOUNT_PT "/ram"
#else
/* Default to RAM disk if no specific access type is selected. */
/* This allows compilation to proceed even if Kconfig is not fully set, */
/* though runtime behavior might be affected if a specific disk is expected. */
#warning "No DISK access type selected, defaulting to RAM disk."
#define DISK_NAME "RAM"
#define DISK_MOUNT_PT "/ram"
#endif

extern struct fs_mount_t fat_mnt;

void test_fat_mount(void);
void test_fat_unmount(void);
void test_fat_format(void);
void test_fat_mkfs(void);
void test_fat_ls(void);
void test_fat_mkdir(void);
void test_fat_rmdir(void);
void test_fat_file_open(void);
void test_fat_file_write(void);
void test_fat_file_read(void);
void test_fat_file_seek(void);
void test_fat_file_tell(void);
void test_fat_file_truncate(void);
void test_fat_file_sync(void);
void test_fat_file_close(void);
void test_fat_file_delete(void);
void test_fat_file_rename(void);
void test_fat_stat(void);
void test_fat_statvfs(void);
void test_fat_dir_open(void);
void test_fat_dir_read(void);
void test_fat_dir_close(void);
void test_fat_dir_delete(void);
void test_fat_dir_rename(void);
void test_fat_rd_only_mount(void);

#endif /* ZEPHYR_TESTS_SUBSYS_FS_FAT_FS_API_SRC_TEST_FAT_H_ */
